var policyTranslations={
 en:{contact:'Contact',back:'← Back to Nawrah Kitchen',delivery:{title:'Delivery information',intro:'Delivery across active areas in Chattogram within 24 hours.',sections:[['Delivery areas and fees',''],['Order confirmation','After you place an order, Nawrah Kitchen reviews and confirms it before preparation. Keep your phone available so we can contact you about delivery.'],['Frozen products','Products are packed for frozen delivery. Move them to a freezer promptly after receiving them and follow the product label for storage and preparation.']]},privacy:{title:'Privacy information',intro:'How Nawrah Kitchen uses information when you browse or place an order.',sections:[['Information we receive','When you create an account or place an order, Nawrah Kitchen may store your name, email address, phone number, delivery address, order details, and any payment transaction reference you submit. Newsletter signups and verified reviews are also stored.'],['Why we use it','We use this information to operate accounts, confirm and deliver orders, answer support requests, process subscriptions, and display verified reviews. We do not request or store card numbers on this site.'],['Services and browser storage','Supabase provides account sign-in, database records, and uploaded images. Google processes Google sign-in if you choose it. Your browser stores your cart, language preference, wishlist, and sign-in session.'],['Your choices','You can update profile information from your account. Contact Nawrah Kitchen to ask about account or subscription information. Some order records may need to be retained to operate the service or meet legal obligations.']]},terms:{title:'Store terms',intro:'These terms explain how orders are handled on the Nawrah Kitchen storefront.',sections:[['Orders and availability','Submitting an order sends a request to Nawrah Kitchen. Current product availability, prices, delivery area, and fee are checked when the order is placed. Orders are confirmed before preparation.'],['Payment','Checkout offers only the payment methods currently enabled by Nawrah Kitchen. Cash on Delivery is collected at delivery. Mobile-wallet payment requires the displayed instructions and verification.'],['Customer details','Provide a reachable phone number and a complete delivery address. Orders may be cancelled before confirmation; confirmed orders cannot be cancelled through the account.'],['Product information','Photos and descriptions help you choose. Follow storage and preparation instructions on product packaging. The final amount is confirmed with your order.']]},returns:{title:'Returns and refunds',intro:'How to report an order issue to Nawrah Kitchen.',sections:[['Report a problem','If an order arrives damaged, incorrect, or incomplete, contact Nawrah Kitchen promptly using the phone or email in the storefront footer. Include your order reference and a short description. Photos can help us review the issue.'],['Review and resolution','Nawrah Kitchen will review the order details and contact you about an appropriate resolution. Refunds or replacements depend on the circumstances and applicable consumer protections. Keep frozen food safely frozen while your request is reviewed.'],['Order cancellation','Orders can be cancelled before confirmation. Confirmed orders cannot be cancelled through the customer account. Contact Nawrah Kitchen for help with an order issue.']] }},
 bn:{contact:'যোগাযোগ',back:'← নওরাহ কিচেনে ফিরে যান',delivery:{title:'ডেলিভারি তথ্য',intro:'চট্টগ্রামের চালু এলাকায় ২৪ ঘণ্টার মধ্যে ডেলিভারি।',sections:[['ডেলিভারি এলাকা ও চার্জ',''],['অর্ডার নিশ্চিতকরণ','অর্ডার জমা দেওয়ার পর প্রস্তুতির আগে Nawrah Kitchen অর্ডারটি যাচাই ও নিশ্চিত করে। ডেলিভারি সংক্রান্ত যোগাযোগের জন্য ফোন সচল রাখুন।'],['ফ্রোজেন পণ্য','পণ্য ফ্রোজেন অবস্থায় প্যাক করা হয়। হাতে পাওয়ার পর দ্রুত ফ্রিজারে রাখুন এবং সংরক্ষণ ও রান্নার জন্য প্যাকেটের নির্দেশনা অনুসরণ করুন।']]},privacy:{title:'গোপনীয়তা তথ্য',intro:'সাইট ব্যবহার বা অর্ডারের সময় Nawrah Kitchen কীভাবে তথ্য ব্যবহার করে।',sections:[['আমরা যে তথ্য পাই','অ্যাকাউন্ট বা অর্ডারের জন্য নাম, ইমেইল, ফোন, ঠিকানা, অর্ডারের বিবরণ এবং পেমেন্ট রেফারেন্স সংরক্ষণ করা হতে পারে। নিউজলেটার সাবস্ক্রিপশন ও যাচাইকৃত রিভিউও সংরক্ষণ করা হয়।'],['তথ্য ব্যবহারের কারণ','অ্যাকাউন্ট চালানো, অর্ডার নিশ্চিত ও ডেলিভারি, সহায়তা, সাবস্ক্রিপশন এবং যাচাইকৃত রিভিউ দেখাতে তথ্য ব্যবহার করা হয়। এই সাইটে কার্ড নম্বর চাওয়া বা সংরক্ষণ করা হয় না।'],['সেবা ও ব্রাউজার স্টোরেজ','অ্যাকাউন্ট, ডেটাবেস ও আপলোডের জন্য Supabase ব্যবহৃত হয়। Google দিয়ে সাইন ইন করলে Google সেই প্রক্রিয়া পরিচালনা করে। ব্রাউজারে কার্ট, ভাষা, উইশলিস্ট ও সাইন-ইন সেশন রাখা হয়।'],['আপনার পছন্দ','অ্যাকাউন্ট থেকে প্রোফাইলের তথ্য পরিবর্তন করতে পারেন। অ্যাকাউন্ট বা সাবস্ক্রিপশনের তথ্য নিয়ে জানতে Nawrah Kitchen-এ যোগাযোগ করুন। সেবা পরিচালনা বা আইনি কারণে কিছু অর্ডার রেকর্ড রাখা হতে পারে।']]},terms:{title:'স্টোরের শর্তাবলি',intro:'Nawrah Kitchen স্টোরে অর্ডার কীভাবে পরিচালিত হয় তা এখানে ব্যাখ্যা করা হয়েছে।',sections:[['অর্ডার ও পণ্যের প্রাপ্যতা','অর্ডার জমা দিলে Nawrah Kitchen-এ অনুরোধ পাঠানো হয়। অর্ডারের সময় পণ্যের প্রাপ্যতা, দাম, ডেলিভারি এলাকা ও চার্জ যাচাই করা হয়। প্রস্তুতির আগে অর্ডার নিশ্চিত করা হয়।'],['পেমেন্ট','চেকআউটে বর্তমানে চালু পেমেন্ট পদ্ধতিই দেখানো হয়। ক্যাশ অন ডেলিভারির মূল্য পণ্য পৌঁছালে পরিশোধ করতে হয়। মোবাইল ওয়ালেটের ক্ষেত্রে দেখানো নির্দেশনা ও যাচাই প্রযোজ্য।'],['ক্রেতার তথ্য','যোগাযোগযোগ্য ফোন নম্বর ও সম্পূর্ণ ঠিকানা দিন। অর্ডার নিশ্চিত হওয়ার আগে বাতিল করা যায়; নিশ্চিত অর্ডার অ্যাকাউন্ট থেকে বাতিল করা যায় না।'],['পণ্যের তথ্য','পণ্যের ছবি ও বিবরণ বেছে নিতে সহায়তা করে। সংরক্ষণ ও রান্নার জন্য প্যাকেটের নির্দেশনা অনুসরণ করুন। অর্ডারের চূড়ান্ত মোট মূল্য নিশ্চিত করা হবে।']]},returns:{title:'রিটার্ন ও রিফান্ড',intro:'অর্ডার সংক্রান্ত সমস্যা Nawrah Kitchen-কে কীভাবে জানাবেন।',sections:[['সমস্যা জানান','অর্ডার ক্ষতিগ্রস্ত, ভুল বা অসম্পূর্ণ হলে দ্রুত ফুটারে দেওয়া ফোন বা ইমেইলে Nawrah Kitchen-এ যোগাযোগ করুন। অর্ডার রেফারেন্স ও সমস্যার সংক্ষিপ্ত বিবরণ দিন। ছবি পর্যালোচনায় সহায়তা করে।'],['পর্যালোচনা ও সমাধান','Nawrah Kitchen অর্ডারের তথ্য পর্যালোচনা করে উপযুক্ত সমাধান জানাবে। পরিস্থিতি ও প্রযোজ্য ভোক্তা সুরক্ষা অনুযায়ী রিফান্ড বা বদলি পণ্য দেওয়া হতে পারে। পর্যালোচনার সময় ফ্রোজেন খাবার নিরাপদে ফ্রিজারে রাখুন।'],['অর্ডার বাতিল','অর্ডার নিশ্চিত হওয়ার আগে বাতিল করা যায়। নিশ্চিত অর্ডার গ্রাহক অ্যাকাউন্ট থেকে বাতিল করা যায় না। অর্ডার সংক্রান্ত সমস্যায় Nawrah Kitchen-এ যোগাযোগ করুন।']]}}
};
